  // Keyboard shortcuts
  useEffect(() => {
    const handleKeyPress = (e) => {
      if (e.ctrlKey || e.metaKey) {
        switch (e.key) {
          case 'z':
          if (e.shiftKey) {
            e.preventDefault();
            redo();
          } else {
            e.preventDefault();
            undo();
          }
          break;
        case 'm':
          e.preventDefault();
          mutateParams();
          break;
        case 's':
          e.preventDefault();
          generateShareLink();
          break;
        default:
          break;
      }
      } else {
        switch (e.key) {
          case ' ':
            e.preventDefault();
            playSound();
            break;
          case 'n':
            setShowNumericInputs(!showNumericInputs);
            break;
          case '1':
          case '2':
          case '3':
          case '4':
          case '5':
          case '6':
          case '7':
          case '8':
            const presetIndex = parseInt(e.key) - 1;
            const presetNames = ['pickupCoin', 'laserShoot', 'explosion', 'powerUp', 'hitHurt', 'jump', 'ambient', 'random'];
            if (presetNames[presetIndex]) {
              loadPreset(presetNames[presetIndex]);
            }
            break;
          case '9':
            loadPreset('blip');
            break;
          case 'q':
            loadPreset('zap');
            break;
          case 'w':
            loadPreset('woosh');
            break;
          case 'e':
            loadPreset('drone');
            break;
          case 'r':
            loadPreset('click');
            break;
          case 't':
            loadPreset('glitch');
            break;
          case 'y':
            loadPreset('portal');
            break;
          case 'u':
            loadPreset('warning');
            break;
          case 'a':
            setActiveSlot('A');
            break;
          case 'b':
            setActiveSlot('B');
            break;
          case 'l':
            toggleLoop();
            break;
          default:
            break;
        }
      }
    };

    window.addEventListener('keydown', handleKeyPress);
    return () => window.removeEventListener('keydown', handleKeyPress);
  }, [undo, redo, playSound, loadPreset, toggleLoop, mutateParams, generateShareLink, showNumericInputs]);

